/**
 * Runes of Hechicero: one original glyph per chord, generated by code (pure, 9x9, '#' = ink).
 *
 * A rune is a spine with a mark on top and four arms. The ROOT picks the four arms (upper-left, upper-right,
 * lower-left, lower-right), the QUALITY the mark: major = one dot, minor = two dots, power chord = bars on both ends.
 * So Em and E share their arms and differ in the mark, and no two chords of the list share a glyph (tested).
 */
import { CHORDS } from '../../exercises/chords';
import type { PaletteKey } from '../../ui/palette';

export const RUNE_SIZE = 9;

/** Arm per slot: 0 none, 1 straight, 2 diagonal, 3 bracket. Order: upper-left, upper-right, lower-left, lower-right. */
const ARMS: Record<number, [number, number, number, number]> = {
  0: [1, 0, 2, 0], // C
  2: [2, 1, 0, 3], // D
  4: [3, 0, 1, 2], // E
  5: [0, 3, 2, 1], // F
  7: [1, 2, 3, 0], // G
  9: [2, 3, 0, 1], // A
};

function armsFor(pc: number): [number, number, number, number] {
  return ARMS[pc] ?? [(pc + 1) % 4, (pc * 3 + 1) % 4, (pc * 5 + 2) % 4, (pc * 7 + 3) % 4];
}

export type Quality = 'major' | 'minor' | 'power';

export function qualityOf(name: string): Quality {
  return /5$/.test(name) ? 'power' : /m$/.test(name) ? 'minor' : 'major';
}

/** Colour of a rune by quality: major amber, minor cyan, power magenta. */
export function runeColor(name: string): PaletteKey {
  const q = qualityOf(name);
  return q === 'major' ? 'amber' : q === 'minor' ? 'cyan' : 'magenta';
}

export function runeGlyph(name: string): string[] {
  const def = CHORDS[name];
  if (!def) throw new Error(`unknown chord ${name}`);
  const g: string[][] = Array.from({ length: RUNE_SIZE }, () => Array<string>(RUNE_SIZE).fill('.'));
  const put = (r: number, c: number) => {
    if (r >= 0 && r < RUNE_SIZE && c >= 0 && c < RUNE_SIZE) g[r][c] = '#';
  };
  for (let r = 1; r <= 7; r++) put(r, 4);
  const q = qualityOf(name);
  if (q === 'major') put(0, 4);
  else if (q === 'minor') {
    put(0, 3);
    put(0, 5);
  } else {
    for (const c of [3, 4, 5]) {
      put(0, c);
      put(8, c);
    }
  }
  const arms = armsFor(def.rootPc);
  // Slot geometry: [top, bottom] rows of the arm and whether it grows to the right.
  const slots = [
    { up: true, right: false },
    { up: true, right: true },
    { up: false, right: false },
    { up: false, right: true },
  ];
  arms.forEach((kind, i) => {
    const { up, right } = slots[i];
    const dir = right ? 1 : -1;
    // r0: row next to the spine, rows run away from the middle row 4 towards the edge.
    const rows = up ? [3, 2, 1] : [5, 6, 7];
    if (kind === 1) {
      for (let k = 1; k <= 3; k++) put(rows[1], 4 + dir * k);
    } else if (kind === 2) {
      rows.forEach((r, k) => put(r, 4 + dir * (k + 1)));
    } else if (kind === 3) {
      for (let k = 1; k <= 3; k++) put(rows[2], 4 + dir * k);
      rows.forEach((r) => put(r, 4 + dir * 3));
    }
  });
  return g.map((row) => row.join(''));
}
